<?php
namespace App\Http\Controllers\HR;use App\Http\Controllers\Controller;use App\Models\{PayrollComponent,PayrollRun};use App\Services\HR\PayrollService;use Illuminate\Http\Request;class PayrollController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('hr.payroll',['runs'=>PayrollRun::with('items')->where('property_id',$p)->latest()->paginate(20),'components'=>PayrollComponent::where('property_id',$p)->get()]);}public function component(Request $r){$p=auth()->user()->property_id;$d=$r->validate(['name'=>'required','code'=>'required|max:40','type'=>'required|in:earning,deduction,employer_cost','calculation'=>'required|in:fixed,percentage','default_value'=>'required|numeric|min:0']);PayrollComponent::updateOrCreate(['property_id'=>$p,'code'=>$d['code']],$d+['property_id'=>$p]);return back()->with('success','Payroll component saved.');}public function generate(Request $r,PayrollService $s){$d=$r->validate(['period_start'=>'required|date','period_end'=>'required|date|after_or_equal:period_start']);$s->generate(auth()->user()->property_id,$d['period_start'],$d['period_end'],auth()->id());return back()->with('success','Draft payroll generated.');}public function approve(PayrollRun $run,PayrollService $s){abort_unless($run->property_id===auth()->user()->property_id,403);$s->approve($run,auth()->id());return back()->with('success','Payroll approved and posted to accounting.');}public function pay(Request $r,PayrollRun $run,PayrollService $s){abort_unless($run->property_id===auth()->user()->property_id,403);$d=$r->validate(['method'=>'required|in:cash,bank_transfer,mtn_momo,airtel_money']);$s->markPaid($run,$d['method'],auth()->id());return back()->with('success','Payroll marked paid and cash/bank entry posted.');}}